Trigger.script:
Persuasion.Tirade = false
Persuasion.Tirade_Tried = {
  Pathos = false,
  Ethos = false,
  Logos = false,
}

local color_table = { ethos = "<SteelBlue>", pathos = "<IndianRed>", logos = "<LimeGreen>",
}
if not table.contains(Persuasion.Evidence, matches[3]) then table.insert(Persuasion.Evidence, matches[3]:title()) cecho("\n "..color_table[matches[3]].."-= WEAK TO "..matches[3]:upper().." =-= WEAK TO "..matches[3]:upper().." =-") end

Script.script:
Persuasion = Persuasion or {}
Persuasion.Last = { Type = "", Count = 0, }
Persuasion.Evidence = {}
Persuasion.Reason = Persuasion.Reason or false Persuasion.Analogy = false Persuasion.RecMorality = false
Persuasion.Current_Appeals = {}
Persuasion.Boon = "" Persuasion.Bane = ""
Persuasion.Target_Max_Resolve = nil Persuasion.Target_Current_Resolve = nil
Persuasion.Tirade = false
-- non-functioning, idk how tirades work Persuasion.Tirade_Tried = { Pathos = false, Ethos = false, Logos = false, }
Persuasion.Attacks = { ["Authority"] = { Type = "Ethos", Blurb = "15% Enemy Damage Debuff for 9s", Reason = "15% Enemy Damage Debuff for 12s", }, ["Morality"] = { Type = "Ethos", Blurb = "Draw 2 appeals next turn", Reason = "Draw 2 appeals next turn, they get 25% lower cost", }, ["Reputation"] = { Type = "Ethos", Blurb = "Gain 1 Influence stack (+5% dmg/stack, Max 5)", Reason = "Gain 2 Influence stack (+5% dmg/stack, Max 5", }, ["Tradition"] = { Type = "Ethos", Blurb = "High damage, Clear debuffs", Reason = "High damage, Clear debuffs, Aff Immune 5s", }, ["Evidence"] = { Type = "Logos", Blurb = "Next Appeal-Type applies Vuln to that type", Reason = "Next Appeal-Type applies Vuln to that type and another random", }, ["Reason"] = { Type = "Logos", Blurb = "Add extra effect to next appeal", Reason = "You're already Reasonable!", }, ["Analogy"] = { Type = "Logos", Blurb = "Next Appeal buffed if Ethos/Pathos, debuffed if Logos", Reason = "Next Appeal extra buffed if Ethos/Pathos, no Logos debuff" }, ["Causality"] = { Type = "Logos", Blurb = "Next 2 Appeals will CRIT", Reason = "Next 2 Appeals will CRIT, Scry next Appeal", }, ["Intimidation"] = { Type = "Pathos", Blurb = "No Affs from enemy's next counterarguement", Reason = "No Affs from next 2 enemy counterarguements", }, ["Reassurance"] = { Type = "Pathos", Blurb = "Low Damage, Recover 10% Acumen", Reason = "Low Damage, Recover 15% Acumen over 10s", }, ["Inspiration"] = { Type = "Pathos", Blurb = "Lowers Cost of Next Appeal", Reason = "Lowers Cost and EQ of Next Appeal", }, ["Provocation"] = { Type = "Pathos", Blurb = "High Damage, but next counterarguement either 2x or 0x damage", Reason = "High Dmg, next counter 2x or 0x. If 2x, recover 25% Acumen, if 0x buff next appeal", }, ["Persuade"] = { Type = "None", }, }
Persuasion.Affs = { conflicted = false, confounded = false, engrossed = false, entrenched = false, fatigued = false, pressured = false, }
Persuasion.Draw_My_Resolve_bar = function() local ret = "<ivory> [" local tenner = tonumber(gmcp.Char.Vitals.maxacu)/10 local bars = math.floor(tonumber(gmcp.Char.Vitals.acu)/tenner) local dashes = 10-bars local percentage = math.floor((tonumber(gmcp.Char.Vitals.acu)/tonumber(gmcp.Char.Vitals.maxacu))*100) if percentage == 100 then bars = 10 dashes = 0 end percentage = "<gold>("..percentage.."%)" for x=0, bars do ret = ret.."<green>|" end if dashes >0 then for y=0, dashes do ret = ret.."<red>-" end end ret = ret.."<ivory>] "..percentage return ret end Persuasion.Draw_Resolve_Bar = function() local ret = "<ivory>[" local tenner = Persuasion.Target_Max_Resolve/10 local bars = math.floor(Persuasion.Target_Current_Resolve/tenner) local dashes = 10-bars local percentage = math.floor((Persuasion.Target_Current_Resolve/Persuasion.Target_Max_Resolve)*100) if percentage == 100 then bars = 10 dashes = 0 end percentage = "<gold>("..percentage.."%)" for x=0, bars do ret = ret.."<green>|" end if dashes >0 then for y=0, dashes do ret = ret.."<red>-" end end ret = ret.."<ivory>] "..percentage return ret end
Persuasion.Reset = function() for k,v in pairs(Persuasion.Affs) do Persuasion.Affs[k] = false end Persuasion.Last.Type = "None" Persuasion.Last.Count = 0 Persuasion.Boon = "" Persuasion.Bane = "" Persuasion.Target_Max_Resolve = nil Persuasion.Target_Current_Resolve = nil Persuasion.Current_Appeals = {} disableTrigger("Persuasion Prompt") disableTrigger("Persuasion Re-Draw") disableAlias("Lost Track") end
